# generated by tools/ail2py.py from json_merge_main.ail; edit the .ail until onelang s16
from json_merge_patch import *
from file_identity import *
from ail import read_bytes, write_bytes
import sys

def main() -> int:
    if len(sys.argv) != 4:
        print('usage: json_merge INPUT PATCH OUTPUT', file=sys.stderr)
        return 2
    try:
        input: str = sys.argv[1]
        patch_path: str = sys.argv[2]
        output: str = sys.argv[3]
        if output == input or output == patch_path:
            raise ValueError
        if file_paths_same(input, output) or file_paths_same(patch_path, output):
            raise ValueError
        target = json_parse_document(read_bytes(input).decode())
        patch = json_parse_document(read_bytes(patch_path).decode())
        report: str = json_render_document(json_merge_patch(target, patch)) + '\n'
        write_bytes(output, report.encode())
        return 0
    except ValueError:
        print('invalid JSON merge document, duplicate member, or output alias', file=sys.stderr)
        return 2
    except OSError:
        print('JSON merge file error', file=sys.stderr)
        return 2
    return 0

if __name__ == "__main__":
    sys.exit(main())
